const crypto = require('crypto');
const secret = $env.PORTAL_TOKEN_SECRET;
if (!secret) throw new Error('PORTAL_TOKEN_SECRET no está definido');
const base = String($env.VRM_PORTAL_URL || 'https://vrm.local/portal').replace(/\/$/, '');
const due = $('Find Due Vendors').all().map(i => i.json);
return $input.all().map(it => {
  const a = it.json;
  const v = due.find(d => d.id === a.vendor_id) || {};
  const payload = Buffer.from(JSON.stringify({
    aid: a.assessment_id, vid: a.vendor_id, exp: Date.now() + 30 * 86400000
  })).toString('base64url');
  const sig = crypto.createHmac('sha256', secret).update(payload).digest('base64url');
  return { json: {
    vendor_id: a.vendor_id, assessment_id: a.assessment_id, legal_name: v.legal_name,
    email: v.email || null, link: base + '/assessment/' + payload + '.' + sig
  }};
});
